ink:0}.rank-list p{display:flex;justify-content:space-between;gap:8px;font-size:10px;margin:11px 0}.rank-list b{color:#d1c9a7;font-weight:400;white-space:nowrap}.poster-footer{margin-top:22px;border-top:2px solid var(--gold);padding-top:10px;display:flex;justify-content:space-between;gap:12px;font-size:9px;color:#c9c5b5}.poster-footer span:last-child{letter-spacing:1px;color:var(--gold)}.board-saved{margin:25px auto 0;text-align:center;color:#7c705b;font-size:11px}.scratch-scene>p{color:#7c705b!important;font-size:11px}.board-backdrop{position:fixed;inset:0;z-index:100;display:flex;align-items:center;justify-content:center;background:#10110ed9;backdrop-filter:blur(7px);padding:20px}.board-dialog{position:relative;background:#2a2c26;border:1px solid var(--gold);padding:32px;width:100%;max-width:440px;text-align:center;border-radius:18px;box-shadow:0 20px 90px #0009;max-height:90dvh;overflow:auto}.dialog-close{position:absolute;top:8px;left:14px;color:#c7bb98;font-size:28px}.dialog-heart{font-size:40px;color:var(--gold);margin-top:12px}.board-dialog h2{font-size:25px;font-weight:800;color:#f6edce}.task-content{font-size:18px;line-height:1.95;margin:18px 0;color:#e2e2d7}.task-points{font-size:12px;color:var(--gold);margin-bottom:18px}.gold-button{display:block;width:100%;background:linear-gradient(120deg,#e4cb87,#b89748);padding:13px 18px;border-radius:9px;font-weight:800;color:#292a26}.gold-button:disabled{opacity:.45;cursor:default}.text-button{color:#b8b8aa;font-size:13px;padding:14px;display:block;width:100%}.task-image{max-height:180px;max-width:100%;border-radius:10px;margin:15px auto;object-fit:contain}.board-finished{color:#5d5239;text-align:center;margin:20px auto}.board-finished h2{font-size:24px;font-weight:800}
    @media(max-width:640px){.scratch-scene{padding:20px 12px 35px}.board-toolbar{font-size:10px;gap:8px;margin-bottom:18px}.board-toolbar>span{display:none}.scratch-poster{padding:10px;transform:none}.poster-frame{padding:17px 12px 10px}.poster-heading{gap:8px;margin-bottom:18px}.poster-heading h1{font-size:27px}.poster-heading p:not(.eyebrow){font-size:9px}.eyebrow{font-size:8px;letter-spacing:1px}.poster-brand{font-size:8px}.poster-seal{width:50px;height:50px;font-size:8px}.poster-score strong{font-size:18px}.poster-score b{font-size:10px}.poster-score span{font-size:8px}.board-hint{font-size:9px;margin-bottom:16px}.level-heading h2{font-size:17px}.level-heading p{font-size:10px;gap:7px}.level-heading b{font-size:17px;letter-spacing:0}.scratch-circles{grid-template-columns:repeat(5,minmax(0,1fr));gap:9px}.scratch-level{margin:20px 0 25px}.poster-bottom{grid-template-columns:1fr 1fr;gap:16px;margin-top:24px;padding-top:18px}.poster-bottom section:last-child{grid-column:1/-1}.rank-list{display:flex;flex-wrap:wrap;gap:5px 14px}.rank-list p{margin:4px 0;gap:6px}.poster-bottom h3{font-size:14px}.poster-option{font-size:10px}.poster-footer{font-size:8px}.poster-footer span:last-child{display:none}.board-dialog{padding:27px 20px}.task-content{font-size:17px}}
    </style>
    @endpush
    @push('scripts')
    <script>
    const gameCards = @json($cards);
    const scratchCardEndpoint = @json(route('games.scratch-card', ['slug' => $game->slug, 'number' => '__NUMBER__']));
    let globalAlpineRoot = null;
    function scratchGame() { return {
        cards:gameCards.map(c=>({...c,level:Number(c.level)||1})),revealedNumbers:[],completedNumbers:[],skippedNumbers:[],bonusIds:[],selectedPlace:'',activeCard:null,resetOpen:false,saveError:false,previousFocus:null,
        storageKey:'scratch-board-v2-{{ $game->id }}-{{ auth()->id() ?? "guest" }}-{{ md5(json_encode($cards)) }}',
        places:['قعدة البيت','البلكونة','ركن هادي','الحديقة','مكان بتحبوه'],
        bonuses:[{id:'music',label:'أغنية اخترتوها سوا',points:1},{id:'letter',label:'رسالة مكتوبة لبعض',points:2},{id:'date',label:'خططتوا لموعد جديد',points:2},{id:'phones',label:'نص ساعة بدون موبايلات',points:3},{id:'memory',label:'حكيتوا ذكرى مميزة',points:2}],
        get revealedCount(){return this.revealedNumbers.length;},
        get score(){return this.cards.filter(c=>this.completedNumbers.includes(c.number)).reduce((s,c)=>s+c.level,0)+this.bonuses.filter(b=>this.bonusIds.includes(b.id)).reduce((s,b)=>s+b.points,0);},
        get rank(){return this.score>=200?'ليلة لا تُنسى':this.score>=150?'نجوم الليلة':this.score>=100?'قلوب متفاهمة':this.score>=50?'أقرب شوية':'شرارة البداية';},
        init(){globalAlpineRoot=this;try{const s=JSON.parse(localStorage.getItem(this.storageKey)||'{}');const valid=v=>Array.isArray(v)?[...new Set(v)].filter(n=>this.cards.some(c=>c.number===n)):[];this.revealedNumbers=valid(s.revealedNumbers);this.completedNumbers=valid(s.completedNumbers).filter(n=>this.revealedNumbers.includes(n));this.skippedNumbers=valid(s.skippedNumbers).filter(n=>this.revealedNumbers.includes(n)&&!this.completedNumbers.includes(n));this.bonusIds=Array.isArray(s.bonusIds)?[...new Set(s.bonusIds)].filter(id=>this.bonuses.some(b=>b.id===id)):[];this.selectedPlace=this.places.includes(s.selectedPlace)?s.selectedPlace:'';}catch(e){this.saveError=true;}},
        save(){try{localStorage.setItem(this.storageKey,JSON.stringify({revealedNumbers:this.revealedNumbers,completedNumbers:this.completedNumbers,skippedNumbers:this.skippedNumbers,bonusIds:this.bonusIds,selectedPlace:this.selectedPlace}));this.saveError=false;}catch(e){this.saveError=true;}},
        markRevealed(n){if(!this.cards.some(c=>c.number===n))return;if(!this.revealedNumbers.includes(n)){this.revealedNumbers.push(n);this.save();}},
        async openTask(n){if(!this.revealedNumbers.includes(n))return;this.previousFocus=document.activeElement;this.activeCard=this.cards.find(c=>c.number===n)||null;this.$nextTick(()=>document.querySelector('.dialog-close')?.focus());try{const response=await fetch(scratchCardEndpoint.replace('__NUMBER__',encodeURIComponent(n)),{headers:{Accept:'application/json'},cache:'no-store'});if(!response.ok)return;const latest=await response.json();const index=this.cards.findIndex(c=>c.number===n);if(index<0)return;this.cards.splice(index,1,{...latest,level:Number(latest.level)||1});if(this.activeCard?.number===n)this.activeCard=this.cards[index];}catch(e){}},
        closeTask(){this.activeCard=null;this.resetOpen=false;this.previousFocus?.focus?.();},
        completeTask(){if(!this.activeCard||this.completedNumbers.includes(this.activeCard.number))return;this.completedNumbers.push(this.activeCard.number);this.skippedNumbers=this.skippedNumbers.filter(n=>n!==this.activeCard.number);this.save();this.closeTask();},
        skipTask(){if(!this.activeCard)return;const n=this.activeCard.number;if(!this.completedNumbers.includes(n)&&!this.skippedNumbers.includes(n))this.skippedNumbers.push(n);this.save();this.closeTask();},
        toggleBonus(id){if(!this.bonuses.some(b=>b.id===id))return;this.bonusIds=this.bonusIds.includes(id)?this.bonusIds.filter(b=>b!==id):[...this.bonusIds,id];this.save();},
        trapFocus(e){const a=[...e.currentTarget.querySelectorAll('button:not([disabled])')].filter(el=>el.offsetParent!==null);if(e.shiftKey&&document.activeElement===a[0]){e.preventDefault();a.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===a.at(-1)){e.preventDefault();a[0]?.focus();}},
        resetGame(){this.revealedNumbers=[];this.completedNumbers=[];this.skippedNumbers=[];this.bonusIds=[];this.selectedPlace='';this.activeCard=null;this.resetOpen=false;document.querySelectorAll('.scratch-silver').forEach(c=>Alpine.$data(c.closest('[x-data]')).resetCard());this.save();}
    };}
    function scratchCard(index){return {
        cardData:gameCards[index],revealed:false,scratching:false,canvas:null,ctx:null,lastX:0,lastY:0,
        init(){this.revealed=globalAlpineRoot.revealedNumbers.includes(this.cardData.number);this.$nextTick(()=>{this.canvas=document.getElementById(`canvas-${index}`);if(!this.canvas)return;this.canvas.width=160;this.canvas.height=160;this.ctx=this.canvas.getContext('2d');this.drawOverlay();});},
        isCompleted(){return globalAlpineRoot?.completedNumbers.includes(this.cardData.number)??false;},openTask(){globalAlpineRoot?.openTask(this.cardData.number);},
        drawOverlay(){const c=this.ctx,w=this.canvas.width,h=this.canvas.height;c.clearRect(0,0,w,h);if(this.revealed)return;const g=c.createLinearGradient(0,0,w,h);g.addColorStop(0,'#e0e4dc');g.addColorStop(.4,'#b5beb4');g.addColorStop(.7,'#d0d6ca');g.addColorStop(1,'#a6b0a4');c.fillStyle=g;c.beginPath();c.arc(w/2,h/2,w/2-1,0,Math.PI*2);c.fill();for(let i=0;i<420;i++){const x=(i*47)%w,y=(i*79)%h;if(Math.hypot(x-w/2,y-h/2)>w/2-2)continue;c.fillStyle=i%2?'#ffffff22':'#46554222';c.fillRect(x,y,1.5,1.5);}c.fillStyle='#58655466';c.textAlign='center';c.textBaseline='middle';c.font='22px Tajawal, sans-serif';c.fillText('✦',w/2,h/2);},
        getPos(e){const r=this.canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*this.canvas.width/r.width,y:(e.clientY-r.top)*this.canvas.height/r.height};},
        startScratch(e){if(this.revealed||!this.ctx)return;this.canvas.setPointerCapture?.(e.pointerId);this.scratching=true;const p=this.getPos(e);this.lastX=p.x;this.lastY=p.y;this.eraseDot(p.x,p.y);},
        doScratch(e){if(!this.scratching||this.revealed)return;const p=this.getPos(e);this.ctx.globalCompositeOperation='destination-out';this.ctx.lineWidth=32;this.ctx.lineCap='round';this.ctx.beginPath();this.ctx.moveTo(this.lastX,this.lastY);this.ctx.lineTo(p.x,p.y);this.ctx.stroke();this.ctx.globalCompositeOperation='source-over';this.lastX=p.x;this.lastY=p.y;this.checkReveal();},
        eraseDot(x,y){this.ctx.globalCompositeOperation='destination-out';this.ctx.beginPath();this.ctx.arc(x,y,16,0,Math.PI*2);this.ctx.fill();this.ctx.globalCompositeOperation='source-over';},
        stopScratch(){if(!this.scratching)return;this.scratching=false;if(!this.revealed)this.checkReveal();},
        checkReveal(){const w=this.canvas.width,h=this.canvas.height,p=this.ctx.getImageData(0,0,w,h).data;let empty=0,total=0;for(let y=0;y<h;y+=3)for(let x=0;x<w;x+=3){if(Math.hypot(x-w/2,y-h/2)>w/2-3)continue;total++;if(p[(y*w+x)*4+3]<128)empty++;}if(total&&empty/total>.48)this.autoReveal();},
        autoReveal(){if(this.revealed){this.openTask();return;}this.revealed=true;this.scratching=false;this.ctx?.clearRect(0,0,this.canvas.width,this.canvas.height);globalAlpineRoot.markRevealed(this.cardData.number);this.openTask();},
        resetCard(){this.revealed=false;this.scratching=false;if(this.ctx)this.drawOverlay();}
    };}
    </script>
    @endpush
</x-app-layout>
